from pathlib import Path
import json,hashlib,zipfile
from datetime import datetime,timezone,timedelta
S=Path(__file__).resolve().parent;E=S/'evidence';ROOT=S.parent.parent
read=lambda n:json.loads((E/n).read_text(encoding='utf-8'))
a=read('resume-acceptance-summary.json');state=read('deployment-state.json');obs=read('observation.json');voice=read('live-deployed-config.json');usage=read('resume-usage-summary.json');manifest=read('resume-source-manifest.json');cleanup=read('memory-cleanup-applied.json')
assert state['phase']=='deployed_verified' and state['finished_at']-state['deployed_at']>=1800
assert all(r['passed'] for r in obs['records']) and voice['passed'] and read('resume-release-gate.json')['passed']
assert read('live-model-route.json')['passed'] and read('memory-cleanup-readback.json')['passed']
assert not a['failed_ids'] and a['real_model_response_turns']>=240 and a['independent_holdout']>=60
pkg=ROOT/'releases/hardware-repair-20261009';m=json.loads((pkg/'manifest.json').read_text(encoding='utf-8'));app_hash=hashlib.sha256((pkg/'xiaozhi.bin').read_bytes()).hexdigest();assert app_hash==m['sha256']['xiaozhi.bin']
text=(pkg/'README.md').read_text(encoding='utf-8').splitlines();text[0]='交付状态：配套服务端已完成自动化验收并部署正式域名，30分钟上线观察已通过。固件已编译，尚未烧录；真实硬件效果需用户烧录后验收。';(pkg/'README.md').write_text('\n'.join(text)+'\n',encoding='utf-8')
for n in m['sha256']:m['sha256'][n]=hashlib.sha256((pkg/n).read_bytes()).hexdigest()
m['device_flashed']=False;m['server_deployed']=True;m['server_version']=manifest['version'];(pkg/'manifest.json').write_text(json.dumps(m,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
hashes={str(f.relative_to(pkg)).replace('\\','/'):hashlib.sha256(f.read_bytes()).hexdigest() for f in pkg.rglob('*') if f.is_file() and f.name!='SHA256SUMS.txt'}
(pkg/'SHA256SUMS.txt').write_text('\n'.join(h+'  '+n for n,h in sorted(hashes.items()))+'\n',encoding='utf-8')
z=ROOT/'releases/hardware-repair-20261009.zip'
with zipfile.ZipFile(z,'w',zipfile.ZIP_DEFLATED,compresslevel=6) as out:
 for f in sorted(pkg.rglob('*')):
  if f.is_file():out.write(f,str(f.relative_to(pkg)).replace('\\','/'))
with zipfile.ZipFile(z) as archive:
 assert archive.testzip() is None
 for n,h in hashes.items():assert hashlib.sha256(archive.read(n)).hexdigest()==h,n
zhash=hashlib.sha256(z.read_bytes()).hexdigest();(E/'firmware-delivery.json').write_text(json.dumps({'zip':str(z),'sha256':zhash,'app_sha256':app_hash,'app_bytes':m['app_size'],'device_flashed':False,'server_version':manifest['version']},indent=2),encoding='utf-8')
time=lambda ts:datetime.fromtimestamp(ts,timezone(timedelta(hours=8))).strftime('%Y-%m-%d %H:%M:%S +08:00')
budget=usage['budget'];pct=lambda x,y:f'{x}/{y}（{x/y*100:.2f}%）'
lines=['# 实机问题修复与正式上线报告','',f"服务端版本：`{manifest['version']}`。正式域名：https://www.realecho.cn 。",f"切换时间：{time(state['deployed_at'])}；观察完成：{time(state['finished_at'])}。",'服务端已上线；固件已编译但未烧录。软件模拟不代表硬件已验收。','','## 最终验收',f"- 最终固定测试集：{a['passed']}/{a['cases']}通过；实际收到模型响应的对话{a['real_model_response_turns']}条，独立保留样本{a['independent_holdout']}条。",f"- 可完成请求：{pct(a['positive_pass'],a['positive_cases'])}；重点操作：{pct(a['common_pass'],a['common_cases'])}；覆盖{a['tools']}项启用工具。",'- 独立保留样本标记经二次审计，排除两条曾参与调试的样本，从63更正为61；原始冻结记录和修正前统计均保留。','- 测试内未发现查询误写、越权、重复创建、虚报成功、原始JSON口播、同轮重复播放或普通监听变化导致的静默。','- 每个业务用例核对参数、关联回执、保存状态、重新查询、最终文本、TTS消息顺序及历史。','- 人工审阅仍见少量模板化表达；只读亮度含义解释里有一次多余的假设举例。实际亮度设置与核验通过，但不把本批自动通过说成聊天已完美。具体见resume-final-review.json。',f"- 完成延迟：P50 {a['latency_ms']['p50']/1000:.2f}秒，P95 {a['latency_ms']['p95']/1000:.2f}秒。这是模型与协议模拟完成时间，包含主模型结果回复，不代表真实摄像头采集或完整语音播放的耗时。",'- Python回归199项、Java真实隔离数据库33项、实际HTTP接口11项通过；固件闹钟11项、视觉16项及异步拍照工作任务6项通过。','- 另验证相对调节15项、回复事实保护14项、卡片/进度13项、卡片展示7项、物流状态9项。真实TTS3次生成成功；视觉2次及认证/会话错误、慢请求专项通过。','','## 修复对应','- 对话生命周期：使用有效请求标识，普通监听变化不取消回复；校验TTS顺序、历史一致及同轮重复发送。','- 工具完整执行：相对音量/亮度读取真实状态后计算、设置并核对；修复真实字段、百分比/档位换算、错引用及查询后漏执行。','- 记忆：本轮查询不能继承历史修改意图；更正和遗忘按记录ID/版本授权定位并读回；短更正事实可查询、继续修改及遗忘。原始聊天保留。','- 回复：正常工具结果交给当前主LLM，遵循原人格和近期反馈；已接收/未知/失败不能说完成。减少闲聊长篇解释，修复普通解释被误拦截以及物流/报告进度编造。','- 声纹：正式数据库、私有配置下发和VoiceprintProvider实际阈值均核验为0.3；后端最低阈值0.2兼容。身份目录、归属和权限校验保留。没有标注录音，真实误识率仍需实机测量。','- 卡片：独立关闭展示，保留业务事项；队列过期、版本、重连和旧回执隔离。新关闭能力需要新固件。','- 闹钟：独立时钟调度、到期实例去重及触发记录，避免聊天/监听重置调度；需要新固件。','- 视觉与音频：当前连接凭据状态、受控刷新及具体错误分类；解析成功包装；拍照/处理/上传移入有界异步任务，音频队列记录积压年龄与丢帧原因；固件部分需烧录。',f"- 历史派生污染：限定设备所属账号，已处理{cleanup['applied']}条确认污染记录，完整15列恢复测试通过，正式库只读核对剩余目标记录0条；原始聊天删除0条，备份及恢复日志仅留服务器。",'- 按要求保留：既有提醒完成判定、设备播报回灌、待机口令及触摸I2C行为。','','## 模型、计费与开销','Qwen3.7-Plus、非思考、温度0.4、原用户人格及官方服务配置保持不变。正式LLM客户端实际地址核验为http://127.0.0.1:3000/v1/，继续经过One-API；计费环境与账号绑定核对通过。工具结果人格化回答会增加部分主模型请求，不使用二次润色模型。',f"累计账本保留：测试{budget['case']['used']}条，主模型请求{budget['model']['used']}次，TTS{budget['tts']['used']}次，视觉{budget['vision']['used']}次；包括旧失败批次、中断和重跑。用户已明确取消原预算上限。",f"最终批次主模型请求分布：{json.dumps(a['model_calls_per_turn'],ensure_ascii=False)}。",'实际token和响应状态见用量证据；未取得网关精确扣费金额，不估算金额。','','## 部署与回滚','磁盘清理及部署备份后，正式服务器只读核对可用空间约2.3GB；用户资料与回滚备份保留。',f"新服务监听就绪后切换，管理API重叠{state['api_overlap_seconds']:.2f}秒。观察{len(obs['records'])}次、至少30分钟，域名、WebSocket认证、内部认证、进程、阈值、模型计费配置、源码及账本检查通过。",'备份：`/root/prjs/releases/hardware-repair-20261009/deploy-backup`。敏感配置、数据库备份不下载到交付目录。','回滚服务：','```bash','/root/miniconda3/envs/xiaozhi-esp32-server/bin/python /root/prjs/releases/hardware-repair-20261009/release.py rollback','```','操作账本保留，避免回滚后重复下发。污染记录独立完整备份，可通过服务器`scoped_memory_cleanup.py restore`恢复；不自动把污染重新导入。','','## 固件与实机限制',f"烧录包：[{z.name}]({z.as_posix()})；SHA256：`{zhash}`。",'解压后关闭串口监视器，在包目录运行：','```powershell','powershell -ExecutionPolicy Bypass -File .\\Upgrade-Preserve.ps1 -Port COM7','```','默认脚本先备份并校验，保留NVS和用户数据；不要把新机清空镜像用于旧机升级。真实摄像头采集、扬声器、物理亮度、设备存储和闹钟触发尚未实机验收。','','## 原文与证据',f"- [完整对话原文]({(E/'resume-dialogues-only.md').as_posix()})",f"- [调用、回执、保存状态及查询核对]({(E/'resume-complete-dialogues.md').as_posix()})",f"- [累计请求与token]({(E/'resume-usage-summary.json').as_posix()})",f"- [逐工具指标]({(E/'resume-acceptance-summary.json').as_posix()})",f"- [上线门槛]({(E/'resume-release-gate.json').as_posix()})",f"- [声纹实际配置]({(E/'live-deployed-config.json').as_posix()})",f"- [上线观察]({(E/'observation.json').as_posix()})",'本轮所有含自动失败记录的批次已建立retained-failures-index.json索引，原文保留在evidence/retained-failed-runs；另保留人工发现问题的批次及审查记录。旧失败既包含产品缺陷，也包含需修正的验收断言，未删除失败样本或用通过结果覆盖它们。本报告的成功率只代表测试集，不保证所有未来自然语言永不失败。','']
